/// VM replay implementations for gpu bindings.
#[inline]
fn destack_gpu_adapter_close_vm_replay(
    runtime: &RuntimeCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    handle: resource::GpuAdapterHandle,
) -> RuntimeResult<vm::Value> {
    let result = runtime.replay().run_binding_with_context(
        GPU_ADAPTER_CLOSE,
        context,
        |context| platform_vm::destack_gpu_adapter_close(runtime, context, handle),
        |context, result| {
            let _ = &context;
            if let Ok(()) = result {
                let result_replay = ();
                let payload = GpuAdapterCloseReplay {
                    result: Ok(result_replay),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(PlatformError::from(error.as_ref()));
                    GpuAdapterCloseReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let _ = &context;
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(RuntimeError::from(error).boxed()),
            }
        },
    );
    let result = encode_destack_gpu_adapter_close_result(context, result)?;
    Ok(result)
}

#[inline]
fn destack_gpu_adapter_list_vm_replay(
    runtime: &RuntimeCallContext,
    context: &mut vm::ExternalCallContext<'_>,
) -> RuntimeResult<vm::Value> {
    let result = runtime.replay().run_binding_with_context(
        GPU_ADAPTER_LIST,
        context,
        |context| platform_vm::destack_gpu_adapter_list(runtime, context),
        |context, result| {
            let _ = &context;
            if let Ok(value) = result {
                let result_value = *value;
                let result_replay_raw = result_value.raw_values(context)?;
                let mut result_replay = Vec::with_capacity(result_replay_raw.len());
                for result_replay_item_value in result_replay_raw {
                    let result_replay_item = {
                        if result_replay_item_value.tag() != vm::ValueTag::Aggregate {
                            return Err(RuntimeError::from(PlatformError::invalid_argument_type(
                                "result_replay_item",
                                "item",
                            ))
                            .boxed());
                        }
                        let slots = context
                            .aggregate_slots(result_replay_item_value)
                            .map_err(|error| RuntimeError::from(error).boxed())?;
                        if slots.len() != 6 {
                            return Err(RuntimeError::from(PlatformError::invalid_argument_value(
                                "result_replay_item",
                                "expected 6 fields",
                            ))
                            .boxed());
                        }
                        let result_replay_item_id =
                            decode_string(slots[0], "result_replay_item_id", "id")?;
                        let result_replay_item_name =
                            decode_string(slots[1], "result_replay_item_name", "name")?;
                        let result_replay_item_backend_raw =
                            decode_uint8(slots[2], "result_replay_item_backend_raw", "backend")?;
                        let result_replay_item_backend = match result_replay_item_backend_raw {
                            1u8 => GpuBackend::Vulkan,
                            2u8 => GpuBackend::Metal,
                            3u8 => GpuBackend::D3D12,
                            4u8 => GpuBackend::OpenGL,
                            255u8 => GpuBackend::Null,
                            _ => {
                                return Err(RuntimeError::from(
                                    PlatformError::invalid_argument_value(
                                        "result_replay_item_backend",
                                        "unknown GpuBackend value",
                                    ),
                                )
                                .boxed());
                            }
                        };
                        let result_replay_item_vendor_id =
                            decode_uint32(slots[3], "result_replay_item_vendor_id", "vendorId")?;
                        let result_replay_item_device_id =
                            decode_uint32(slots[4], "result_replay_item_device_id", "deviceId")?;
                        let result_replay_item_integrated =
                            decode_bool(slots[5], "result_replay_item_integrated", "integrated")?;
                        GpuAdapterInfoVm {
                            id: result_replay_item_id,
                            name: result_replay_item_name,
                            backend: result_replay_item_backend,
                            vendor_id: result_replay_item_vendor_id,
                            device_id: result_replay_item_device_id,
                            integrated: result_replay_item_integrated,
                        }
                    };
                    let result_replay_item_replay_id = {
                        let result_replay_item_replay_id_ref = context
                            .string_ref(result_replay_item.id)
                            .map_err(|error| RuntimeError::from(error).boxed())?;
                        result_replay_item_replay_id_ref.as_str().to_string()
                    };
                    let result_replay_item_replay_name = {
                        let result_replay_item_replay_name_ref = context
                            .string_ref(result_replay_item.name)
                            .map_err(|error| RuntimeError::from(error).boxed())?;
                        result_replay_item_replay_name_ref.as_str().to_string()
                    };
                    let result_replay_item_replay_backend = result_replay_item.backend;
                    let result_replay_item_replay_vendor_id = result_replay_item.vendor_id;
                    let result_replay_item_replay_device_id = result_replay_item.device_id;
                    let result_replay_item_replay_integrated = result_replay_item.integrated;
                    let result_replay_item_replay = GpuAdapterInfoReplay {
                        id: result_replay_item_replay_id,
                        name: result_replay_item_replay_name,
                        backend: result_replay_item_replay_backend,
                        vendor_id: result_replay_item_replay_vendor_id,
                        device_id: result_replay_item_replay_device_id,
                        integrated: result_replay_item_replay_integrated,
                    };
                    result_replay.push(result_replay_item_replay);
                }
                let payload = GpuAdapterListReplay {
                    result: Ok(result_replay),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(PlatformError::from(error.as_ref()));
                    GpuAdapterListReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let _ = &context;
            // replay result
            match payload.result {
                Ok(value) => {
                    let mut vm_result_values = Vec::with_capacity(value.len());
                    for vm_result_item in value.iter() {
                        let vm_result_item = vm_result_item.clone();
                        let vm_result_item_value_id_value =
                            context.intern_string(vm_result_item.id.as_str());
                        let vm_result_item_value_id =
                            vm::StringHandle::new(vm_result_item_value_id_value);
                        let vm_result_item_value_name_value =
                            context.intern_string(vm_result_item.name.as_str());
                        let vm_result_item_value_name =
                            vm::StringHandle::new(vm_result_item_value_name_value);
                        let vm_result_item_value_backend = vm_result_item.backend;
                        let vm_result_item_value_vendor_id = vm_result_item.vendor_id;
                        let vm_result_item_value_device_id = vm_result_item.device_id;
                        let vm_result_item_value_integrated = vm_result_item.integrated;
                        let vm_result_item_value = GpuAdapterInfoVm {
                            id: vm_result_item_value_id,
                            name: vm_result_item_value_name,
                            backend: vm_result_item_value_backend,
                            vendor_id: vm_result_item_value_vendor_id,
                            device_id: vm_result_item_value_device_id,
                            integrated: vm_result_item_value_integrated,
                        };
                        let vm_result_item_value_encoded = {
                            let field_0 = vm_result_item_value.id.value();
                            let field_1 = vm_result_item_value.name.value();
                            let field_2 =
                                vm::Value::uint(vm_result_item_value.backend as u8 as u64, 8);
                            let field_3 =
                                vm::Value::uint(vm_result_item_value.vendor_id as u64, 32);
                            let field_4 =
                                vm::Value::uint(vm_result_item_value.device_id as u64, 32);
                            let field_5 = vm::Value::bool(vm_result_item_value.integrated);
                            context.allocate_aggregate(vec![
                                field_0, field_1, field_2, field_3, field_4, field_5,
                            ])
                        };
                        vm_result_values.push(vm_result_item_value_encoded);
                    }
                    let vm_result_data = context.allocate_raw_values(vm_result_values);
                    let vm_result: VmSlice<GpuAdapterInfoVm> = VmSlice {
                        data: vm_result_data,
                        len: value.len() as u32,
                        _marker: std::marker::PhantomData,
                    };
                    Ok(vm_result)
                }
                Err(error) => Err(RuntimeError::from(error).boxed()),
            }
        },
    );
    let result = encode_destack_gpu_adapter_list_result(context, result)?;
    Ok(result)
}

